package audit
import("encoding/json";"os";"path/filepath";"testing";"github.com/relux-works/curator/internal/capabilities")
func TestResearchConfiguredBackendMustRunOrRefuse(t *testing.T){
 subject:=subjectWith(t,"#!/bin/sh\necho harmless\n",capabilities.ImplicitNone(),3)
 cfg:=newCfg(t,"strict","high");cfg.Audit.Backend="synthetic-unimplemented";cfg.Audit.Model="synthetic-model"
 _,errs:=Gate(cfg,[]Subject{subject});files,err:=filepath.Glob(filepath.Join(cfg.Home(),"audit","*","verdict-*.json"));if err!=nil{t.Fatal(err)}
 label:="";for _,f:=range files{b,err:=os.ReadFile(f);if err!=nil{t.Fatal(err)};var v map[string]any;if err:=json.Unmarshal(b,&v);err!=nil{t.Fatal(err)};label,_=v["backend"].(string)}
 t.Logf("Gate blocking-errors=%d verdicts=%d backend-label=%s",len(errs),len(files),label)
 if len(errs)==0{t.Fatal("expected explicit unsupported-backend refusal; static audit returned allow")}
}

package gitops
import("os";"path/filepath";"testing";"strings")
func TestResearchGitRejectsSkillShim(t *testing.T) {
 for _, shape := range []string{"direct", "intermediate-link"} { t.Run(shape,func(t *testing.T){
  root:=t.TempDir(); if err:=os.Mkdir(filepath.Join(root,".git"),0755);err!=nil{t.Fatal(err)}; shim:=filepath.Join(root,".agents","bin"); trusted:=filepath.Join(root,"trusted"); marker:=filepath.Join(root,"called")
  for _,d:=range []string{shim,trusted}{if err:=os.MkdirAll(d,0755);err!=nil{t.Fatal(err)}}
  payload:="#!/bin/sh\nprintf called > '"+marker+"'\nprintf 'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\\n'\n"
  pathEntry:=shim
  if shape=="direct" { if err:=os.WriteFile(filepath.Join(shim,"git"),[]byte(payload),0755);err!=nil{t.Fatal(err)} } else {
   real:=filepath.Join(trusted,"real-git"); if err:=os.WriteFile(real,[]byte(payload),0755);err!=nil{t.Fatal(err)}
   if err:=os.Symlink(real,filepath.Join(shim,"git"));err!=nil{t.Fatal(err)}
   if err:=os.Symlink(filepath.Join(shim,"git"),filepath.Join(trusted,"git"));err!=nil{t.Fatal(err)}; pathEntry=trusted
  }
  t.Setenv("PATH",pathEntry+":/usr/bin:/bin")
  _,err:=Resolve(root,"revision",strings.Repeat("a",40)); _,called:=os.Stat(marker)
  t.Logf("Resolve accepted=%v; shim-chain executable invoked=%v",err==nil,called==nil)
  if called==nil {t.Fatal("expected rejection before executing a skill-shim path")}
 })}
}

func TestResearchAggregateSnapshotBudget(t *testing.T){
 entries:=[]treeEntry{}
 for _,name:=range []string{"a","b","c","d","e"}{entries=append(entries,treeEntry{mode:"100644",kind:"blob",path:name,size:512<<20})}
 plan,err:=planWrites(t.TempDir(),entries)
 t.Logf("preflight entries=%d declared-total-bytes=%d accepted=%v; no blob payload written",len(plan),int64(5)*(512<<20),err==nil)
 if err==nil{t.Fatal("expected proposed 2 GiB aggregate refusal; actual implementation has only per-file bound")}
}

