package install
import("encoding/json";"os";"os/exec";"path/filepath";"strings";"testing")
func researchManifest(t *testing.T,e *env, commands map[string]any, dependencies map[string]any, script string) {
 t.Helper(); dir:=filepath.Join(e.skillsRoot,"consumer")
 e.write(dir,"scripts/consumer-tool",script)
 spec:=map[string]any{"schema_version":4,"capabilities":map[string]any{},"runtime_roots":[]string{"scripts"},"commands":commands}
 if dependencies!=nil {spec["dependencies"]=map[string]any{"commands":dependencies}}
 b,err:=json.Marshal(spec);if err!=nil{t.Fatal(err)};e.write(dir,"csk-skill.json",string(b));e.git(dir,"commit","-qam","probe");e.git(dir,"tag","-f","v1");e.declare("consumer")
}
func TestResearchReservedCommandsRejected(t *testing.T) {
 for _,name:=range []string{"git","curator","ssh-add","GiT.ExE"}{t.Run(name,func(t *testing.T){
  e:=newEnv(t);e.skill("consumer");researchManifest(t,e,map[string]any{name:map[string]any{"type":"script","unix_path":"scripts/consumer-tool"}},nil,"#!/bin/sh\nprintf harmless\\n\n")
  result:=e.install(Options{DryRun:true});t.Logf("Project dry-run status=%s",result.Status)
  if result.Status=="ok"{t.Fatal("expected reserved-command refusal; ordinary plan accepted name")}
  if !strings.Contains(strings.Join(result.Errors," "),"reserved"){t.Fatalf("unrelated refusal: %v",result.Errors)}
 })}
}
func TestResearchSystemDependencyDoesNotPreemptAmbient(t *testing.T){
 e:=newEnv(t);e.skill("consumer");root:=t.TempDir();preferred:=filepath.Join(root,"preferred");dependency:=filepath.Join(root,"dependency")
 for _,dir:=range []string{preferred,dependency}{if err:=os.MkdirAll(dir,0755);err!=nil{t.Fatal(err)}}
 for _,f:=range []struct{dir,name,answer string}{{preferred,"gap-choice","preferred"},{dependency,"gap-choice","dependency"},{dependency,"declared-helper","helper"}}{if err:=os.WriteFile(filepath.Join(f.dir,f.name),[]byte("#!/bin/sh\nprintf '"+f.answer+"\\n'\n"),0755);err!=nil{t.Fatal(err)}}
 t.Setenv("PATH",preferred+":"+dependency+":/usr/bin:/bin")
 researchManifest(t,e,map[string]any{"consumer-tool":map[string]any{"type":"script","unix_path":"scripts/consumer-tool"}},map[string]any{"declared-helper":map[string]any{"type":"system","command":"declared-helper"}},"#!/bin/sh\ngap-choice\n")
 result:=e.install(Options{});if result.Status!="ok"{t.Fatalf("fixture install failed: %v",result.Errors)}
 cmd:=exec.Command(filepath.Join(e.project,".agents","bin","consumer-tool"));cmd.Env=[]string{"PATH="+preferred+":/usr/bin:/bin"};out,err:=cmd.CombinedOutput();if err!=nil{t.Fatal(err)}
 t.Logf("installed launcher selected=%s",strings.TrimSpace(string(out)))
 if strings.TrimSpace(string(out))!="preferred"{t.Fatal("expected inherited PATH before dependency suffix")}
}
func TestResearchSSHAddRejectsSkillShim(t *testing.T){
 root:=t.TempDir();shim:=filepath.Join(root,".agents","bin");if err:=os.MkdirAll(shim,0755);err!=nil{t.Fatal(err)}
 if err:=os.WriteFile(filepath.Join(shim,"ssh-add"),[]byte("#!/bin/sh\nprintf 'synthetic-entry\\n'\n"),0755);err!=nil{t.Fatal(err)}
 t.Setenv("PATH",shim+":/usr/bin:/bin");count,known:=sshAgentKeyCount(filepath.Join(root,"nonexistent-synthetic-socket"))
 t.Logf("sshAgentKeyCount count=%d known=%v",count,known)
 if known{t.Fatal("expected no execution of ssh-add from skill shim; no real agent was used")}
}
